# CASO-LIM-011 · score setter [0, 1]
# DEFECT: no valida rango ni nan
from math import isfinite

class Signal:
    def __init__(self):
        self._score = 0.0

    @property
    def score(self) -> float:
        return self._score

    @score.setter
    def score(self, value: float) -> None:
        self._score = float(value)

s = Signal()
s.score = 0.4
print("ok", s.score)
s.score = 1.5
print("ok", s.score)
s.score = float("nan")
print("ok", s.score)

# CASO-LIM-011 · mutable hash bug
# DEFECT: no muestra SAFE frozen
class MutableEntity:
    def __init__(self, eid, name):
        self.eid = eid
        self.name = name
    def __hash__(self):
        return hash((self.eid, self.name))
    def __eq__(self, o):
        return isinstance(o, MutableEntity) and (self.eid, self.name) == (o.eid, o.name)

m = MutableEntity("E1", "Ana")
d = {m: "row"}
m.name = "Ana P"
